const R=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
const pick=a=>a[Math.floor(Math.random()*a.length)];
const shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const gcd=(a,b)=>b?gcd(b,a%b):Math.abs(a);
const frac=(n,d)=>{if(d<0){n=-n;d=-d;}const g=gcd(n,d)||1;n/=g;d/=g;return d===1?`${n}`:`${n}/${d}`;};
const sgn=(c,first)=>c<0?(first?'-':' - '):(first?'':' + ');
const term=(c,v,first)=>{if(c===0)return'';const a=Math.abs(c);return sgn(c,first)+((a===1&&v)?'':a)+v;};
const poly=ts=>{let s='',f=true;for(const[c,v]of ts){if(c===0)continue;s+=term(c,v,f);f=false;}return s||'0';};
const fmt=x=>{const v=Math.round(x*1e6)/1e6;return String(Object.is(v,-0)?0:v);}; // no float junk like 0.30000000004
const pn=n=>n<0?`(${n})`:`${n}`;                    // wrap negatives in ( )
const xm=(n)=>n<0?`x + ${-n}`:`x - ${n}`;            // "x - n" written nicely (n is the root)
const mono=(c,n)=>(c===1?'':c===-1?'-':c)+'x'+(n===1?'':'^'+n);
const NONZ=(a,b)=>{let v=0;while(v===0)v=R(a,b);return v;};
const pmin=n=>n<0?'−'+(-n):String(n);
// numeric multiple choice: answer + "common mistake" alts + nearby numbers (never negative if the answer isn't)
function numQ(q,ans,explain,alts){const a=String(ans);const set=new Set([a]);const out=[a];
 (alts||[]).forEach(x=>{x=String(x);if(!set.has(x)&&x!=='NaN'&&out.length<4){set.add(x);out.push(x);}});
 const n=parseFloat(a),neg=n<0;let t=0;while(out.length<4&&t++<80){let d;
  if(!isNaN(n)&&/^-?\d+(\.\d+)?$/.test(a)){const dec=(a.split('.')[1]||'').length;const unit=dec?Math.pow(10,-dec):1;const step=Math.max(1,Math.round(Math.abs(n)*0.15/unit));
   const v=n+pick([-1,1])*R(1,Math.min(step,10)+2)*unit;if(!neg&&v<0)continue;d=dec?v.toFixed(dec):String(Math.round(v));if(d==='-0')continue;}else d=a+'?';
  if(!set.has(d)){set.add(d);out.push(d);}}
 return{q,choices:shuffle(out.slice(0,4)),answer:a,explain};}
function mc(q,ans,wrong,explain){const w=shuffle([...new Set(wrong.filter(x=>x!==ans))]).slice(0,3);return{q,choices:shuffle([ans,...w]),answer:ans,explain};}
const cnt=(from,k,dir=1)=>Array.from({length:k},(_,i)=>from+dir*(i+1)).join(', ');

