const puncM=()=>{const p=pick(PUNC_MS);return mc('Which is punctuated correctly?',p[0],[p[1],p[0].replace(/[.,!]/g,''),p[1].replace(',',''),p[1].replace(/[.!]$/,''),p[0].replace(/[.!]$/,',')],[p[2],`Correct: ${p[0]}`])};
