const DEVX={chiasmus:'Chiasmus flips the order of words in the second half ("what your country can do for you" → "what you can do for your country").',anaphora:'Anaphora repeats the same words at the START of each phrase ("we shall fight… we shall fight…").',metonymy:'Metonymy uses something closely related to stand for the thing ("pen" = writing, "sword" = force).',synecdoche:'Synecdoche uses a PART to mean the whole ("hands" = workers/sailors).',oxymoron:'An oxymoron puts two opposite words together (deafening + silence).','verbal irony':'Verbal irony: saying the opposite of what you mean ("great" about a flat tire).','rhetorical question':'A rhetorical question is asked for effect; the answer is obvious.',antithesis:'Antithesis sets opposite ideas side by side in matching form (best / worst).',asyndeton:'Asyndeton leaves out the "and" between items in a list.','situational irony':'Situational irony: the opposite of what you\'d expect happens (a FIRE station burns).','dramatic irony':'Dramatic irony: the audience knows something a character doesn\'t.',litotes:'Litotes is understatement with a double negative ("not unaware" = very aware).',apostrophe:'Apostrophe speaks directly to someone absent or something not human (here, Death).',ethos:'Ethos appeals to the speaker\'s credibility or expertise.',pathos:'Pathos appeals to emotions (sympathy for hungry children).',logos:'Logos appeals to logic, facts, and numbers.',imagery:'Imagery uses vivid sensory details to paint a picture.',allusion:'An allusion refers to a well-known story, person, or event (the myth of Icarus).'};
const DEV=[['Ask not what your country can do for you—ask what you can do for your country.','chiasmus',['antithesis']],['We shall fight on the beaches, we shall fight on the landing grounds…','anaphora'],['The pen is mightier than the sword.','metonymy'],['All hands on deck.','synecdoche'],['A deafening silence.','oxymoron'],['"Oh, great, another flat tire."','verbal irony'],['Is the pope Catholic?','rhetorical question'],['It was the best of times, it was the worst of times.','antithesis',['anaphora']],['He was tired, hungry, cold, alone.','asyndeton'],['The fire station burned down.','situational irony'],['The audience knows the killer hides upstairs; the hero does not.','dramatic irony'],['He was not unaware of the risk.','litotes'],['Death, be not proud.','apostrophe'],['As a doctor with 20 years of experience, I recommend…','ethos'],['Think of the children who will go hungry tonight.','pathos'],['Studies show a 40% drop in crime.','logos'],['The golden leaves glowed in the soft evening light.','imagery'],['Like Icarus, he flew too close to the sun.','allusion']];
const DEVN=[...new Set(DEV.map(d=>d[1]))];
const dev=()=>{const d=pick(DEV);return mc(`Identify the device: "${d[0]}"`,d[1],DEVN.filter(n=>!(d[2]||[]).includes(n)),[DEVX[d[1]]])};
const GRAM=[['Each of the students ___ a book.','has',['have','are having','were having'],'"Each" is singular (each ONE), so use "has".'],['Neither the coach nor the players ___ ready.','were',['was','is being','has been'],'With "neither…nor", the verb agrees with the nearer subject: "players" → were.'],['Between you and ___, this is easy.','me',['I','myself','mine'],'After a preposition ("between"), use an object pronoun: me.'],['___ did you invite?','Whom',['Who','Whose','Who\'s'],'You invited HIM → him = whom (object).'],['She runs ___ than her brother.','faster',['more faster','fastest','more fast'],'Comparing two: short words add -er. Never "more" + -er.'],['If I ___ you, I would study.','were',['was','am','be'],'Imaginary "if" situations use "were" (subjunctive).'],['These criteria ___ important.','are',['is','was','be'],'"Criteria" is plural (one criterion, many criteria) → are.'],['The jury ___ reached its verdict.','has',['have','were','are'],'The jury acts as one group ("its verdict") → singular "has".'],['There are ___ people here than yesterday.','fewer',['less','lesser','littler'],'Use "fewer" for things you can count (people).'],['The effect of the drugs ___ unclear.','is',['are','were','have been'],'The subject is "effect" (singular), not "drugs" → is.'],['He has ___ the book on the table.','laid',['lain','lay','lied'],'"Lay" means to put something down; past form is "laid".'],['Having finished the test, ___','the students left early.',['the test was handed in.','it was time to leave.','the bell rang.'],'The opening phrase must describe who finished — the students.']];
const gram=()=>{const g=pick(GRAM);return mc(g[0],g[1],g[2],[g[3]])};
const PUNC=[['I have three goals: travel, learn, and grow.','I have three goals; travel, learn, and grow.','A colon introduces a list after a complete sentence.'],['It rained; we stayed inside.','It rained, we stayed inside.','A semicolon joins two complete sentences. A comma alone there is a comma splice.'],['My sister, who lives in Ohio, is a nurse.','My sister who lives in Ohio, is a nurse.','Extra (nonessential) info gets a comma on BOTH sides.'],['The children\'s toys were everywhere.','The childrens\' toys were everywhere.','"Children" is already plural, so add \'s: children\'s.'],['My brother—who never cooks—made dinner.','My brother—who never cooks, made dinner.','Dashes come in pairs around an interruption.'],['However, the plan failed.','However the plan failed.','Put a comma after an opening transition like "However".'],['"Did she say, \'Wait\'?" he asked.','"Did she say "Wait"?" he asked.','A quote inside a quote uses single quotation marks.'],['It\'s a well-known fact.','Its a well known fact.','It\'s = it is; "well-known" before a noun gets a hyphen.'],['We left the house early, but the traffic on the highway was heavy.','We left the house early but, the traffic on the highway was heavy.','The comma goes BEFORE "but" when it joins two sentences.'],['The movie, which was long, ended at ten.','The movie which, was long ended at ten.','"Which was long" is extra info — commas on both sides.']];
const punc=()=>{const p=pick(PUNC);const bad2=p[0].replace(/[;:,—]/,'').replace(/  +/g,' ');return mc('Which sentence is punctuated correctly?',p[0],[p[1],bad2,p[0].replace(/[.?]"?$/,m=>m.length>1?'"':''),p[1].replace(/[.?]"?$/,m=>m.length>1?'"':'')],[p[2],`Correct: ${p[0]}`])};
const EDIT=[['The reason is because he was late.','The reason is that he was late.',['The reason is due to the fact that he was late.','Because he was late is the reason.'],'"The reason is because" says the same thing twice. Use "the reason is that".'],['Walking to school, the rain soaked me.','Walking to school, I got soaked by the rain.',['The rain soaked me, walking to school.','Walking to school the rain, soaked me.'],'The rain wasn\'t walking — put "I" right after the opening phrase.'],['I like hiking, to swim, and biking.','I like hiking, swimming, and biking.',['I like to hike, swimming, and biking.','I like hiking, to swim, and to bike.'],'Items in a list should match (all -ing words).'],['She is a person who is very kind and who helps everyone always.','She is kind and helps everyone.',['She is a person who is kind and very helpful always to everyone.','She, a kind person, who helps everyone.'],'Cut extra words; keep the meaning.'],['The book was read by me.','I read the book.',['The book, by me, was read.','Reading the book was done by me.'],'Active voice (who did it comes first) is clearer.'],['Me and him went to the store.','He and I went to the store.',['Him and I went to the store.','Me and he went to the store.'],'Use subject pronouns (he, I) for the subject. Test: "He went" ✓, "Me went" ✗.'],['He went to the store he bought milk.','He went to the store and bought milk.',['He went to the store, he bought milk.','He went to the store he, bought milk.'],'Two sentences jammed together (run-on). Join them with "and".'],['Because it was raining.','We stayed in because it was raining.',['Because it was raining, so.','Because, it was raining.'],'"Because it was raining" is not a full thought (fragment). Add the main idea.'],['Everyone should bring their own lunch tomorrow, in my opinion I think.','Everyone should bring a lunch tomorrow.',['In my opinion I think everyone should bring their own lunch.','Everyone, in my opinion, I think, should bring lunch.'],'"In my opinion" and "I think" say the same thing — cut both.'],['The committee have reached their decisions about it.','The committee has reached its decision.',['The committee have reached its decision.','The committees has reached their decision.'],'A committee acts as one → "has" and "its".']];
const edit=()=>{const e=pick(EDIT);return mc(`Best revision of: "${e[0]}"`,e[1],e[2].concat([e[0]]),[e[3]])};
const ARG=[['Claim: Schools should start later. Which is the strongest evidence?','A study found teens who started at 8:30 had 20% fewer absences.',['Many students say they feel tired.','My cousin hates waking up early.','Starting later is just common sense.'],'Strong evidence is specific and measurable, like a study with numbers.'],['"Everyone is buying this phone, so it must be the best." This is…','bandwagon fallacy',['ad hominem','straw man','false dilemma'],'Bandwagon: "everyone does it, so it\'s right." Popular ≠ best.'],['"You can\'t trust his tax plan; he\'s been divorced twice." This is…','ad hominem',['slippery slope','appeal to authority','red herring'],'Ad hominem attacks the person instead of the argument.'],['"Either we ban cars or the planet is doomed." This is…','false dilemma',['hasty generalization','circular reasoning','bandwagon'],'False dilemma pretends there are only two choices.'],['"If we allow phones in class, soon students will never learn anything." This is…','slippery slope',['straw man','ad hominem','false cause'],'Slippery slope claims one step will lead to an extreme result, without proof.'],['"I wore my lucky socks and we won, so the socks caused the win." This is…','false cause (post hoc)',['appeal to emotion','straw man','equivocation'],'Something happening first doesn\'t mean it CAUSED what came next.'],['A writer acknowledges an opposing view, then refutes it. This is a…','counterargument and rebuttal',['thesis','hook','anecdote'],'Counterargument = the other side; rebuttal = answering it.'],['Which statement is a claim rather than a fact?','Remote work is better for families.',['The survey had 1,200 respondents.','The law passed in 2019.','Water boils at 100°C at sea level.'],'A claim can be argued; facts can be checked.'],['"She says we should fund parks; she must want to cut police funding." This is…','straw man',['ad hominem','bandwagon','appeal to tradition'],'Straw man twists someone\'s argument into something easier to attack.'],['"It\'s true because the book says so, and the book is true." This is…','circular reasoning',['false cause','red herring','slippery slope'],'Circular reasoning uses the conclusion as its own proof.'],['"Three of my friends got sick after eating sushi, so sushi is dangerous." This is…','hasty generalization',['bandwagon','false dilemma','straw man'],'Hasty generalization draws a big conclusion from too few examples.'],['Which best weakens the claim "Homework improves grades"?','A large study found no grade difference between schools with and without homework.',['Some students dislike homework.','Teachers assign homework every night.','Homework takes time.'],'To weaken a claim, find evidence that directly shows it isn\'t true.']];
const arg=()=>{const a=pick(ARG);return mc(a[0],a[1],a[2],[a[3]])};
const passX=q=>[q[3]||'Look back at the passage and find the sentence that answers the question.','Tip: the answer is always backed up by words in the passage.'];
const PASS=[{t:'The lighthouse keeper had not spoken to another person in eleven months. Each night he lit the lamp, not because ships still passed—few did—but because the ritual was the last thread tying him to the world he had abandoned.',qs:[['Why does the keeper light the lamp?','It connects him to the world he left.',['Many ships still need it.','He is ordered to.','He fears the dark.'],'"The ritual was the last thread tying him to the world he had abandoned."'],['The tone of the passage is best described as…','melancholy',['comic','furious','celebratory'],'Eleven months alone, a world abandoned — the mood is sad and thoughtful (melancholy).'],['"The last thread" is an example of…','metaphor',['simile','hyperbole','onomatopoeia'],'The ritual is called a "thread" without "like" or "as" — a metaphor.']]},
{t:'Critics of standardized testing argue that it narrows curricula, rewarding memorization over inquiry. Proponents counter that without common measures, inequities between schools remain invisible. Both sides, however, agree that a single score cannot capture a student\'s full ability.',qs:[['The main purpose of the passage is to…','present two views and a point of agreement',['argue for abolishing tests','describe how tests are scored','tell a story about a student'],'It gives the critics\' view, the proponents\' view, then what "both sides… agree" on.'],['"Proponents" most nearly means…','supporters',['opponents','students','examiners'],'Proponents "counter" the critics, so they are on the other side — supporters.'],['What do both sides agree on?','One score can\'t capture full ability.',['Tests should be eliminated.','Curricula are too broad.','Inequities are invisible.'],'"Both sides… agree that a single score cannot capture a student\'s full ability."']]},
{t:'When the first photographs of Earth from space were published, many viewers reported a sudden sense of the planet\'s fragility. Historians later credited the images with energizing the modern environmental movement, though the causes of that movement were surely more complex.',qs:[['The author\'s attitude toward the historians\' claim is…','cautiously skeptical',['wholly approving','openly hostile','indifferent'],'"Though the causes… were surely more complex" — the author doubts the claim a little, politely.'],['"Fragility" most nearly means…','delicateness',['strength','size','beauty'],'Seeing Earth as small and alone made it feel easily harmed — delicate.'],['The word "surely" signals that the author…','believes other causes existed',['doubts the photos existed','is joking','agrees completely'],'"Surely more complex" = the author is confident there were other causes too.']]},
{t:'Marisol had practiced the concerto for a year, yet when the stage lights rose, her hands felt like borrowed things. Then the first note sounded—clear, almost defiant—and the hall disappeared.',qs:[['"Her hands felt like borrowed things" suggests she felt…','disconnected and nervous',['proud and confident','bored','angry'],'Hands that feel "borrowed" don\'t feel like her own — she is nervous.'],['What shift occurs in the passage?','from anxiety to absorption',['from joy to sorrow','from past to future','from silence to applause'],'Nervous at first, then "the hall disappeared" — she is lost in the music.'],['"Defiant" most nearly means…','boldly resistant',['quiet','mistaken','gentle'],'A "defiant" note pushes back boldly — here, against her fear.']]},
{t:'Economists define opportunity cost as the value of the next-best alternative given up. A student who spends an evening at a concert gives up not only the ticket price but also the hours that might have been spent studying or working.',qs:[['Opportunity cost is…','the value of the next-best alternative forgone',['the ticket price only','the total of all costs','money saved'],'The first sentence defines it: "the value of the next-best alternative given up."'],['The concert example functions as…','an illustration of a definition',['a counterargument','a personal anecdote of the author','a statistic'],'The concert example shows the definition in action.'],['Which would be an opportunity cost of studying all night?','missing a friend\'s party',['buying a textbook','earning a good grade','learning the material'],'Opportunity cost is what you GIVE UP — here, the party.']]}];
const PASS_EL=[{t:'Max the puppy loved the park. Every morning he ran to the pond in the park to chase the ducks. The ducks always flew away, but Max never stopped trying. One day a duck landed right next to him. Max was so surprised that he sat down and just watched it.',qs:[['Where did Max go every morning?','the park',['the beach','school','the store'],'"Every morning he ran to the pond in the park."'],['What did Max do when the duck landed next to him?','He sat and watched it.',['He chased it.','He barked loudly.','He ran home.'],'"He sat down and just watched it."'],['Which word best describes Max?','playful',['lazy','mean','sleepy'],'He runs and chases ducks every day — that\'s playful.']]},
{t:'Lena planted a tiny seed in a pot. She watered it every day and set it in the sunny window. After a week, a green sprout poked out of the soil. Lena smiled. "Patience works," she said.',qs:[['What did Lena plant?','a seed',['a tree','a flower she bought','a rock'],'"Lena planted a tiny seed in a pot."'],['Why did she put the pot in the window?','so it would get sunlight',['to hide it','to keep it cold','so the cat could see it'],'It was the SUNNY window — plants need sunlight to grow.'],['What lesson does Lena learn?','Patience pays off.',['Plants grow overnight.','Water is bad for plants.','Windows are pretty.'],'She waited a whole week and said, "Patience works."']]},
{t:'Octopuses are clever sea animals. They have eight arms and can change the color of their skin to hide from enemies. Some octopuses even use coconut shells as portable shelters!',qs:[['How many arms does an octopus have?','eight',['six','ten','four'],'"They have eight arms."'],['Why do octopuses change color?','to hide from enemies',['to look pretty','to stay warm','to find food'],'"Change the color of their skin to hide from enemies."'],['What is the main idea?','Octopuses are clever animals.',['Coconuts grow in the sea.','Fish have arms.','The ocean is cold.'],'The first sentence gives the main idea; the rest are details that prove it.']]},
{t:'Jamal was nervous about the spelling bee. He practiced with his grandmother each night, spelling words while she cooked dinner. On the big day, his last word was "kitchen." Jamal grinned—he had spelled it a hundred times beside her stove.',qs:[['Who helped Jamal practice?','his grandmother',['his teacher','his brother','a coach'],'"He practiced with his grandmother each night."'],['Why did Jamal grin at his last word?','He had practiced it in the kitchen many times.',['He didn\'t know it.','The bee was over.','He was hungry.'],'"He had spelled it a hundred times beside her stove."'],['How did Jamal feel at the start?','nervous',['bored','angry','sleepy'],'The first sentence: "Jamal was nervous."']]}];
const PASS_MS=[{t:'The Great Wall of China was not built all at once. Different dynasties added sections over nearly two thousand years, using materials found nearby—stone in the mountains, packed earth in the deserts. The result is less a single wall than a patchwork of many.',qs:[['Why were different materials used?','Builders used what was available locally.',['Stone was banned.','Emperors liked variety.','Earth was stronger than stone.'],'"Using materials found nearby — stone in the mountains, packed earth in the deserts."'],['"Patchwork" suggests the wall is…','made of many different pieces',['perfectly uniform','brand new','made of cloth'],'A patchwork is many pieces joined together — like the wall\'s many sections.'],['The main idea is that the wall…','was built in stages over a long time',['was built in one year','is only in deserts','is made only of stone'],'"Not built all at once… over nearly two thousand years."']]},
{t:'Priya hated losing at chess to her older brother. Instead of quitting, she began studying his favorite openings. Three weeks later she won—and to her surprise, the victory felt smaller than the satisfaction of having figured him out.',qs:[['How did Priya respond to losing?','She studied her brother\'s strategies.',['She quit chess.','She asked for a rematch immediately.','She played someone else.'],'"Instead of quitting, she began studying his favorite openings."'],['What surprised Priya?','Understanding his play felt better than winning.',['She lost again.','Her brother cheated.','Chess was boring.'],'"The victory felt smaller than the satisfaction of having figured him out."'],['A theme of the passage is…','persistence and learning matter more than winning',['family is unimportant','games are a waste of time','luck decides everything'],'She kept working, and learning felt better than the win.']]},
{t:'Honeybees communicate through a "waggle dance." By moving in a figure-eight and shaking their bodies, scout bees tell others the direction and distance of flowers. The longer the waggle, the farther the food.',qs:[['What does the waggle dance communicate?','the direction and distance of food',['danger from predators','the queen\'s location','the weather'],'"Tell others the direction and distance of flowers" (food).'],['A longer waggle means…','the food is farther away',['the food is closer','there is more danger','the bee is tired'],'"The longer the waggle, the farther the food."'],['This passage is mainly…','informational',['persuasive','a poem','a personal story'],'It teaches facts — that\'s informational text.']]},
{t:'Many towns are replacing grass lawns in parks with native wildflowers. Supporters say the plants need less water and attract pollinators. Some residents complain that the parks now look "messy," but water bills for the town have dropped by a third.',qs:[['What is one benefit of the wildflowers?','They use less water.',['They look neater.','They cost more.','They keep bees away.'],'"Supporters say the plants need less water."'],['Which detail supports the supporters\' view?','Water bills dropped by a third.',['Residents call the parks messy.','Parks used to have grass.','Towns have parks.'],'Lower water bills prove the plants use less water.'],['Why is "messy" in quotation marks?','It quotes the residents\' opinion.',['It is a title.','It is a scientific term.','It is a mistake.'],'Quotation marks show the exact word the residents used.']]}];
PASS.push({t:'In 1854, physician John Snow mapped cholera deaths in London and noticed they clustered around a single water pump on Broad Street. Though many experts believed the disease spread through "bad air," Snow persuaded officials to remove the pump\'s handle. Cases soon fell, and his map became a founding document of epidemiology.',qs:[['Snow\'s evidence was primarily…','the pattern of deaths around the pump',['a laboratory experiment','interviews with doctors','the smell of the air'],'He "mapped cholera deaths" and saw they "clustered around a single water pump."'],['The "bad air" theory is presented as…','the prevailing view Snow challenged',['Snow\'s own theory','proven correct','a later discovery'],'"Many experts believed" it — the common view Snow went against.'],['"Founding document" suggests the map was…','foundational to a new field',['the first map ever drawn','a legal contract','later proven false'],'"Founding" = it helped start the field of epidemiology.']]},
{t:'Some philosophers argue that boredom is not merely unpleasant but useful: it signals that our current activity lacks meaning and pushes us to seek something better. On this view, eliminating boredom entirely—through constant entertainment—may deprive us of an important guide.',qs:[['According to the passage, boredom is useful because it…','signals a lack of meaning and prompts change',['helps us sleep','is always pleasant','improves memory'],'"It signals that our current activity lacks meaning and pushes us to seek something better."'],['The author implies constant entertainment may…','silence a valuable signal',['cure all boredom safely','make people smarter','have no effect'],'Removing boredom "may deprive us of an important guide."'],['"Deprive" most nearly means…','take away from',['give to','explain','confuse'],'To deprive someone of something is to take it away.']]});
const passBand=list=>()=>{const p=pick(list),q=pick(p.qs);return Object.assign(mc(q[0],q[1],q[2],passX(q)),{passage:p.t})};
