[[plural,'Plurals'],[pos,'Parts of speech'],[prefix,'Prefixes'],[hom,'Homophones'],[fig,'Figurative language'],[puncM,'Punctuation'],[dev,'Rhetoric & literary devices'],[gram,'Grammar & usage'],[punc,'Punctuation'],[edit,'Sentence editing'],[arg,'Argument & evidence'],[passQ,'Reading passages'],[passEL,'Reading passages'],[passEL3,'Reading passages'],[passMS,'Reading passages'],[HSROOT,'Roots']].forEach(([g,n])=>TAG.set(g,n));
Object.keys(E).forEach(l=>E[l].forEach(g=>{if(!TAG.has(g)){const src=g.toString();TAG.set(g,src.includes('root "')?'Roots':'Vocabulary');}}));
const genFor=(subject,level)=>(subject==='math'?M:E)[level]||[];
var skillsFor=function(subject,level){return[...new Set(genFor(subject,level).map(g=>TAG.get(g)))];};
var makeQuiz=function(subject,level,n=10,skill){let gens=genFor(subject,level);if(skill){const f=gens.filter(g=>TAG.get(g)===skill);if(f.length)gens=f;}const seen=new Set(),out=[];let t=0;
 while(out.length<n&&t++<800){const g=pick(gens),q=g();const k=q.q+'|'+q.answer;if(seen.has(k)||q.choices.length<2||!q.choices.includes(q.answer))continue;seen.add(k);q.skill=TAG.get(g)||'General';q.subj=subject;out.push(q);}
 // small skill pools (e.g. one fixed question) can't fill n unique questions; that's fine
 return out;};
if(typeof module!=='undefined')module.exports={M,E,LEVELS,makeQuiz,skillsFor,PASS,PASS_EL,PASS_MS,TAG,genFor,SAT,ROOTS,MVOC,FIG,DEV,GRAM,PUNC,PUNC_MS,EDIT,ARG,HOM,PL,SYN,ANT,RHY,PREF,near};

// ===== STUDY CARDS (one per skill). what = the idea, steps = how to do it, ex = worked example, tip = a trick =====
const STUDY={
// ---- Math: early grades ----
'Counting':{i:'🔢',what:'Counting tells us how many things there are.',steps:['Touch or point to each thing once.','Say one number for each thing: 1, 2, 3 …','The LAST number you say is how many.'],ex:{q:'How many? 🍎🍎🍎🍎',a:['Point and count: 1, 2, 3, 4.','The last number is 4.','There are 4 apples.']},tip:'The number AFTER a number is one more: after 6 comes 7.'},
'Addition & subtraction':{i:'➕',what:'Adding puts groups together (more). Subtracting takes some away (less).',steps:['Adding: start at the bigger number and count UP.','Subtracting: start at the first number and count BACK.','Or think: subtraction is "what do I add to get there?"'],ex:{q:'8 + 3 = ?   and   9 - 4 = ?',a:['8 + 3: start at 8, count up 3 → 9, 10, 11. Answer 11.','9 - 4: start at 9, count back 4 → 8, 7, 6, 5. Answer 5.']},tip:'Two-digit numbers: add the ONES first, then the TENS. If the ones make 10 or more, carry a ten.'},
'Number sense':{i:'⚖️',what:'Comparing numbers: which is bigger and which is smaller.',steps:['Count up from 1.','The number you reach LATER is bigger.','Adding 0 keeps a number the same.'],ex:{q:'Which is bigger: 4 or 7?',a:['Count: 1, 2, 3, 4 … 5, 6, 7.','You reach 7 later.','7 is bigger.']},tip:'Think of a number line: bigger numbers are farther to the right.'},
'Place value':{i:'🏠',what:'Each digit has a job based on where it sits: ones, tens, hundreds.',steps:['The digit on the right is the ONES.','Next to the left is the TENS.','Next is the HUNDREDS.'],ex:{q:'What does 345 mean?',a:['3 hundreds = 300','4 tens = 40','5 ones = 5','300 + 40 + 5 = 345']},tip:'10 more = the tens digit goes up by 1 (37 → 47).'},
'Money':{i:'🪙',what:'Each coin is worth a number of cents (¢).',steps:['Quarter = 25¢, dime = 10¢, nickel = 5¢, penny = 1¢.','Count the biggest coins first.','Add them all together.'],ex:{q:'2 quarters + 1 dime + 1 nickel',a:['Quarters: 25 + 25 = 50¢','Dime: 50 + 10 = 60¢','Nickel: 60 + 5 = 65¢']},tip:'Skip-count: quarters by 25s (25, 50, 75), dimes by 10s, nickels by 5s.'},
'Multiply & divide':{i:'✖️',what:'Multiplying is adding equal groups fast. Dividing splits into equal groups.',steps:['3 × 4 means 3 groups of 4.','Skip count: 4, 8, 12.','Division is the opposite: 12 ÷ 3 asks "3 times what is 12?"'],ex:{q:'23 ÷ 4 = ?',a:['4 × 5 = 20 fits. 4 × 6 = 24 is too big.','Left over: 23 - 20 = 3.','Answer: 5 R3']},tip:'Big numbers: break them apart. 324 × 3 = 300×3 + 20×3 + 4×3 = 900 + 60 + 12 = 972.'},
'Rounding':{i:'🎯',what:'Rounding makes a number simpler, close to the real one.',steps:['Find the place you round to (tens).','Look at the digit just to the RIGHT (ones).','5 or more → round up. 4 or less → round down.'],ex:{q:'Round 347 to the nearest ten.',a:['Ones digit is 7.','7 is 5 or more → round up.','347 → 350']},tip:'"5 or more, raise the score. 4 or less, let it rest."'},
'Fractions & decimals':{i:'🍕',what:'A fraction is part of a whole. Top = parts you have, bottom = equal parts in all.',steps:['Same bottom? Add the tops, keep the bottom.','Equal fractions: multiply top AND bottom by the same number.','Decimals: line up the decimal points, then add like whole numbers.'],ex:{q:'2/8 + 3/8 = ?',a:['Bottoms are the same (8).','Add the tops: 2 + 3 = 5.','Answer: 5/8']},tip:'Never add the bottoms! 1/4 + 1/4 = 2/4 (= 1/2), not 2/8.'},
'Geometry & measurement':{i:'📐',what:'Measuring shapes: around the outside, inside, and how much they hold.',steps:['Perimeter = add all the sides (around).','Area = length × width (squares inside).','Volume = length × width × height (cubes inside).','Circle: circumference C = 2 × π × r (π ≈ 3.14).'],ex:{q:'A rectangle is 5 by 3.',a:['Perimeter: 5 + 3 + 5 + 3 = 16','Area: 5 × 3 = 15 square units']},tip:'Perimeter is the fence. Area is the grass.'},
'Factors':{i:'🧩',what:'Factors are numbers that multiply together to make a number.',steps:['Start with 1 × the number.','Try 2, 3, 4 … and find pairs.','Stop when the pairs start repeating.'],ex:{q:'How many factors does 12 have?',a:['Pairs: 1×12, 2×6, 3×4.','Factors: 1, 2, 3, 4, 6, 12.','12 has 6 factors.']},tip:'A prime number has exactly 2 factors: 1 and itself.'},
'Order of operations':{i:'🪜',what:'When there\'s more than one step, do them in the right order.',steps:['Parentheses first.','Then exponents.','Then × and ÷ (left to right).','Then + and − (left to right).'],ex:{q:'3 × (4 + 2) = ?',a:['Parentheses: 4 + 2 = 6.','Then 3 × 6 = 18.']},tip:'Remember PEMDAS: Please Excuse My Dear Aunt Sally.'},
// ---- Math: middle school ----
'Ratios & percents':{i:'📊',what:'A ratio compares two amounts. A percent means "out of 100".',steps:['Equal ratios: multiply both sides by the same number.','Percent → decimal: 25% = 0.25.','"Of" means multiply: 25% of 80 = 0.25 × 80.','Unit rate: divide the total by how many.'],ex:{q:'A $60 shirt is 25% off. Sale price?',a:['Discount: 0.25 × 60 = $15.','Sale price: 60 − 15 = $45.']},tip:'10% is easy: move the decimal one place left. Then build other percents from it.'},
'Integers':{i:'🌡️',what:'Integers include negative numbers, like temperatures below zero.',steps:['Same signs: add the sizes, keep the sign.','Different signs: subtract the sizes, keep the sign of the bigger size.','Multiplying: same signs → +, different signs → −.'],ex:{q:'-7 + 3 = ?   and   (-4) × (-5) = ?',a:['-7 + 3: sizes 7 and 3 → 7 − 3 = 4; bigger size was negative → -4.','(-4) × (-5): 4 × 5 = 20; same signs → +20.']},tip:'On a number line, adding a negative moves LEFT.'},
'Equations & expressions':{i:'⚖️',what:'An equation is a balance. Whatever you do to one side, do to the other.',steps:['Undo adding/subtracting first.','Then undo multiplying/dividing.','Check by putting your answer back in.'],ex:{q:'Solve: 3x + 5 = 20',a:['Subtract 5 from both sides: 3x = 15.','Divide both sides by 3: x = 5.','Check: 3 × 5 + 5 = 20 ✓']},tip:'Variables on both sides? Move all the x\'s to one side first.'},
'Slope & lines':{i:'📈',what:'Slope tells how steep a line is: rise over run.',steps:['Slope m = (y₂ − y₁) ÷ (x₂ − x₁).','In y = mx + b, m is the slope.','b is the y-intercept: where the line crosses the y-axis.'],ex:{q:'Slope through (1, 2) and (3, 8)?',a:['Rise: 8 − 2 = 6.','Run: 3 − 1 = 2.','Slope = 6 ÷ 2 = 3.']},tip:'Uphill left-to-right = positive slope. Downhill = negative.'},
'Pythagorean theorem':{i:'📐',what:'In a right triangle: a² + b² = c², where c is the longest side (hypotenuse).',steps:['Square the two legs.','Add them.','Take the square root.'],ex:{q:'Legs 6 and 8. Hypotenuse?',a:['6² + 8² = 36 + 64 = 100.','√100 = 10.']},tip:'Famous sets: 3-4-5, 5-12-13, 8-15-17 (and their multiples like 6-8-10).'},
'Exponents':{i:'🚀',what:'An exponent says how many times to multiply a number by itself.',steps:['2⁴ = 2 × 2 × 2 × 2 = 16.','Same base multiplying → ADD exponents: 2³ × 2² = 2⁵.','Fraction exponent: bottom = root, top = power.'],ex:{q:'8^(2/3) = ?',a:['Bottom 3 → cube root: ∛8 = 2.','Top 2 → square: 2² = 4.']},tip:'Don\'t multiply the exponents when multiplying powers — add them!'},
'Square roots':{i:'🟩',what:'The square root asks: what number times itself makes this?',steps:['Think of the perfect squares: 1, 4, 9, 16, 25, 36, 49, 64, 81, 100, 121, 144.','√ of a perfect square is the number you squared.'],ex:{q:'√49 = ?',a:['7 × 7 = 49.','So √49 = 7.']},tip:'√ undoes squaring: √(9²) = 9.'},
// ---- Math: high school ----
'Linear equations':{i:'⚖️',what:'Solve for x by doing the same thing to both sides until x is alone.',steps:['Undo + or − first.','Then undo × or ÷.','Check your answer in the original.'],ex:{q:'Solve: 4x − 7 = 13',a:['Add 7: 4x = 20.','Divide by 4: x = 5.','Check: 4(5) − 7 = 13 ✓']},tip:'Watch negatives: −3x = 12 → x = −4.'},
'Factoring':{i:'🧩',what:'Factoring x² + bx + c means writing it as (x + m)(x + n).',steps:['Find two numbers that MULTIPLY to c.','…and ADD to b.','Write (x + m)(x + n).'],ex:{q:'Factor x² + 5x + 6',a:['Multiply to 6, add to 5: 2 and 3.','(x + 2)(x + 3)','Check by FOIL: x² + 3x + 2x + 6 ✓']},tip:'If c is negative, the two numbers have different signs.'},
'Systems':{i:'🔀',what:'A system is two equations that are both true at once.',steps:['Elimination: add or subtract the equations to cancel a variable.','Solve for the one that\'s left.','Plug back in for the other.'],ex:{q:'x + y = 10, x − y = 4',a:['Add them: 2x = 14.','x = 7.','Then y = 10 − 7 = 3.']},tip:'Always check your pair in BOTH equations.'},
'Polynomials':{i:'🧮',what:'Multiplying two binomials uses FOIL: First, Outer, Inner, Last.',steps:['First: x · x = x²','Outer + Inner: combine the x terms.','Last: multiply the numbers.'],ex:{q:'(x + 2)(x + 5)',a:['First: x²','Outer + Inner: 5x + 2x = 7x','Last: 2 × 5 = 10','= x² + 7x + 10']},tip:'Middle number = ADD the two numbers; last number = MULTIPLY them.'},
'Inequalities':{i:'↔️',what:'Inequalities (<, >, ≤, ≥) solve just like equations — with one twist.',steps:['Solve like an equation.','If you multiply or divide by a NEGATIVE, flip the sign.'],ex:{q:'Solve: 3x + 2 > 11',a:['Subtract 2: 3x > 9.','Divide by 3 (positive, no flip): x > 3.']},tip:'−2x > 6 → x < −3 (flipped because we divided by −2).'},
'Triangles':{i:'🔺',what:'The three angles of any triangle add up to 180°.',steps:['Add the angles you know.','Subtract from 180.'],ex:{q:'Angles 50° and 60°. Third?',a:['50 + 60 = 110.','180 − 110 = 70°.']},tip:'A right angle is 90°, so the other two angles in a right triangle add to 90°.'},
'Circles':{i:'⭕',what:'Circle formulas use the radius r (center to edge).',steps:['Area A = πr².','Circumference C = 2πr.','Diameter = 2r.'],ex:{q:'Area with radius 5?',a:['r² = 25.','A = 25π.']},tip:'Area has r SQUARED (it covers space). Circumference doesn\'t.'},
'Polygons':{i:'⬡',what:'The interior angles of an n-sided polygon add to (n − 2) × 180°.',steps:['Count the sides, n.','Subtract 2.','Multiply by 180.'],ex:{q:'Hexagon (6 sides)?',a:['6 − 2 = 4.','4 × 180 = 720°.']},tip:'Why? You can cut it into (n − 2) triangles from one corner.'},
'Angles':{i:'📐',what:'Supplementary angles add to 180°. Complementary angles add to 90°.',steps:['Supplement: 180 − angle.','Complement: 90 − angle.'],ex:{q:'Supplement of 65°?',a:['180 − 65 = 115°.']},tip:'S comes after C, like 180 comes after 90: Supplementary = 180, Complementary = 90.'},
'Coordinate geometry':{i:'🗺️',what:'Distance between two points comes from the Pythagorean theorem.',steps:['Find how far across (Δx) and how far up (Δy).','d = √(Δx² + Δy²).'],ex:{q:'(1, 2) to (4, 6)?',a:['Across 3, up 4.','√(9 + 16) = √25 = 5.']},tip:'Draw the right triangle between the points — it helps!'},
'Similarity':{i:'🔍',what:'Similar shapes have the same shape but different sizes.',steps:['Find the scale factor.','Multiply every side by it.'],ex:{q:'Scale factor 3, side 4?',a:['4 × 3 = 12.']},tip:'Angles stay the same in similar shapes — only the sides change.'},
'Area':{i:'🟦',what:'Area is the space inside a shape.',steps:['Rectangle: A = length × width.','Triangle: A = ½ × base × height.'],ex:{q:'Triangle base 10, height 6?',a:['½ × 10 × 6 = 30.']},tip:'A triangle is half a rectangle — that\'s where the ½ comes from.'},
'Quadratics':{i:'🏹',what:'Quadratics have x². Their graph is a U-shaped parabola.',steps:['Roots: factor, then set each factor = 0.','Vertex form y = (x − h)² + k → vertex (h, k).'],ex:{q:'Roots of x² − x − 6 = 0?',a:['Factor: (x − 3)(x + 2) = 0.','x − 3 = 0 → x = 3; x + 2 = 0 → x = −2.']},tip:'In (x − 3), the root is +3: the sign flips!'},
'Logarithms':{i:'🪵',what:'A log asks: what power do I need? log₂ 8 = 3 because 2³ = 8.',steps:['log_b(N) asks: b to what power = N?','log(ab) = log a + log b.','log(a/b) = log a − log b.'],ex:{q:'log base 3 of 81?',a:['3¹=3, 3²=9, 3³=27, 3⁴=81.','Answer: 4.']},tip:'Logs turn multiplying into adding — that\'s why they were invented!'},
'Complex numbers':{i:'🌀',what:'i is the number where i² = −1.',steps:['Multiply like binomials (FOIL).','Replace i² with −1.','Combine the real parts.'],ex:{q:'(3 + 2i)(3 − 2i)',a:['= 9 − 6i + 6i − 4i²','= 9 − 4(−1) = 9 + 4 = 13']},tip:'(a + bi)(a − bi) is always a² + b² — a real number.'},
'Functions':{i:'⚙️',what:'f(x) is a machine: put x in, get an output.',steps:['Replace every x with the number (use parentheses!).','Follow order of operations.'],ex:{q:'f(x) = 2x² + 1. f(−3)?',a:['(−3)² = 9.','2 × 9 + 1 = 19.']},tip:'(−3)² = 9, but −3² = −9. Parentheses matter!'},
'Sequences':{i:'🔁',what:'A geometric sequence multiplies by the same number r each time.',steps:['aₙ = a₁ · r^(n−1).'],ex:{q:'a₁ = 2, r = 3. Term 4?',a:['2 · 3³ = 2 · 27 = 54.','(2, 6, 18, 54 ✓)']},tip:'Arithmetic sequences ADD the same number; geometric ones MULTIPLY.'},
'Unit circle':{i:'🧭',what:'On the unit circle, each angle\'s point is (cos θ, sin θ).',steps:['sin = y-value, cos = x-value.','tan = sin ÷ cos.','Key angles: 0°, 30°, 45°, 60°, 90°.'],ex:{q:'sin 30°, cos 30°, tan 30°',a:['sin 30° = 1/2','cos 30° = √3/2','tan 30° = (1/2) ÷ (√3/2) = 1/√3 = √3/3']},tip:'sin goes 0, 1/2, √2/2, √3/2, 1 as the angle goes 0°, 30°, 45°, 60°, 90°. cos goes the other way.'},
'Radians':{i:'🥧',what:'Radians are another way to measure angles. 180° = π.',steps:['Degrees → radians: multiply by π/180.','Simplify the fraction.'],ex:{q:'120° in radians?',a:['120 × π/180 = 120π/180.','Divide by 60: 2π/3.']},tip:'90° = π/2, 60° = π/3, 45° = π/4, 30° = π/6.'},
'Function composition':{i:'🪆',what:'f(g(x)) means: do g first, then put that answer into f.',steps:['Work from the inside out.','Find g(x).','Put that into f.'],ex:{q:'f(x) = x + 1, g(x) = 2x². f(g(3))?',a:['g(3) = 2 × 9 = 18.','f(18) = 19.']},tip:'f(g(x)) and g(f(x)) are usually different!'},
'Inverse functions':{i:'↩️',what:'An inverse undoes a function.',steps:['Write y = f(x).','Swap x and y.','Solve for y.'],ex:{q:'Inverse of f(x) = 3x + 2',a:['x = 3y + 2','x − 2 = 3y','y = (x − 2)/3']},tip:'Check: f(f⁻¹(x)) should give back x.'},
'Trig graphs':{i:'〰️',what:'y = sin(bx) repeats every 2π ÷ b.',steps:['Find b (the number next to x).','Period = 2π ÷ b.'],ex:{q:'Period of sin(4x)?',a:['2π ÷ 4 = π/2.']},tip:'Bigger b → squished wave → shorter period.'},
'Identities':{i:'🪪',what:'Identities are true for every angle.',steps:['sin²θ + cos²θ = 1.','tan θ = sin θ ÷ cos θ.'],ex:{q:'If sin θ = 3/5, cos²θ = ?',a:['sin²θ = 9/25.','cos²θ = 1 − 9/25 = 16/25.']},tip:'It comes from the unit circle: x² + y² = 1.'},
'Mean':{i:'⚖️',what:'The mean (average) shares everything out equally.',steps:['Add all the numbers.','Divide by how many there are.'],ex:{q:'Mean of 4, 8, 9?',a:['4 + 8 + 9 = 21.','21 ÷ 3 = 7.']},tip:'One really big or small number (outlier) pulls the mean a lot.'},
'Median':{i:'🎯',what:'The median is the middle number when the numbers are in order.',steps:['Sort from smallest to largest.','Pick the middle one.'],ex:{q:'Median of 9, 2, 7, 4, 5?',a:['Sorted: 2, 4, 5, 7, 9.','Middle: 5.']},tip:'Always SORT first — the middle of the unsorted list is a trap!'},
'Range':{i:'↕️',what:'Range = largest − smallest. It shows how spread out data is.',steps:['Find the biggest.','Find the smallest.','Subtract.'],ex:{q:'Range of 12, 3, 25, 8?',a:['25 − 3 = 22.']},tip:'Scan the whole list carefully for the max and min.'},
'Probability':{i:'🎲',what:'Probability = favorable outcomes ÷ total outcomes.',steps:['Count what you want.','Count everything possible.','Independent events: multiply.'],ex:{q:'3 red, 2 blue. P(red)?',a:['Total: 5.','Red: 3.','P = 3/5.']},tip:'Probabilities are between 0 (never) and 1 (always).'},
'Combinations':{i:'🤝',what:'Combinations count groups where order doesn\'t matter.',steps:['nCr = n! ÷ (r!(n − r)!).','Shortcut: multiply r numbers counting down from n, then divide by r!.'],ex:{q:'Choose 2 from 5?',a:['(5 × 4) ÷ (2 × 1) = 20 ÷ 2 = 10.']},tip:'If order matters (like 1st and 2nd place), it\'s a permutation — don\'t divide by r!.'},
// ---- Math: college ----
'Limits':{i:'🎯',what:'A limit is the value a function approaches as x gets close to a number.',steps:['Try plugging in.','If you get 0/0, factor and cancel, then plug in.','Remember: lim x→0 sin(x)/x = 1.'],ex:{q:'lim x→3 of (x² − 9)/(x − 3)',a:['Plug in → 0/0.','Factor: (x − 3)(x + 3)/(x − 3) = x + 3.','Plug in 3: 6.']},tip:'0/0 doesn\'t mean "no answer" — it means "do more work".'},
'Derivatives':{i:'📉',what:'A derivative is the slope (rate of change) of a function.',steps:['Power rule: d/dx[axⁿ] = a·n·xⁿ⁻¹.','Do each term separately.','Know: sin → cos, cos → −sin, eˣ → eˣ, ln x → 1/x.'],ex:{q:'f(x) = 3x² + 4x. f′(2)?',a:['f′(x) = 6x + 4.','f′(2) = 12 + 4 = 16.']},tip:'The derivative of a constant is 0.'},
'Integrals':{i:'∫',what:'Integrating reverses the derivative (and finds area).',steps:['Add 1 to the exponent.','Divide by the new exponent.','Indefinite: add + C. Definite: top minus bottom.'],ex:{q:'∫ 6x² dx',a:['x² → x³/3.','6/3 = 2.','= 2x³ + C']},tip:'Check by taking the derivative of your answer.'},
'Domain':{i:'🚧',what:'The domain is all the x-values allowed.',steps:['Square roots: inside must be ≥ 0.','Fractions: bottom can\'t be 0.'],ex:{q:'Domain of √(x − 4)?',a:['x − 4 ≥ 0.','x ≥ 4.']},tip:'Set up an inequality for whatever can\'t happen.'},
'Exponential equations':{i:'💥',what:'Solve by writing both sides with the same base.',steps:['Rewrite the number as a power of the base.','Set the exponents equal.'],ex:{q:'2^x = 32',a:['32 = 2⁵.','x = 5.']},tip:'If you can\'t match bases, take the log of both sides.'},
'Interest':{i:'💵',what:'Simple interest: I = P × r × t.',steps:['P = starting money.','r = rate as a decimal (5% = 0.05).','t = years.'],ex:{q:'$2,000 at 5% for 3 years',a:['2000 × 0.05 × 3 = $300.']},tip:'Always change the percent to a decimal first.'},
'Absolute value':{i:'📏',what:'|x| is the distance from 0, so it\'s never negative.',steps:['|stuff| = 0 only when stuff = 0.','|stuff| = 5 means stuff = 5 OR stuff = −5.'],ex:{q:'|x − 4| = 0',a:['x − 4 = 0 → x = 4.']},tip:'|x| = −3 has NO solution.'},
'Z-scores':{i:'📏',what:'A z-score says how many standard deviations a value is from the mean.',steps:['z = (x − μ) ÷ σ.','Or flip it: x = μ + zσ.'],ex:{q:'Mean 70, SD 10, z = −2?',a:['x = 70 + (−2)(10) = 50.']},tip:'Negative z = below the mean.'},
'Normal distribution':{i:'🔔',what:'Bell-curve data follows the 68–95–99.7 rule.',steps:['68% within 1 SD.','95% within 2 SD.','99.7% within 3 SD.'],ex:{q:'Mean 100, SD 15. 95% fall between?',a:['2 SD = 30.','70 to 130.']},tip:'The curve is symmetric: half the data is above the mean.'},
'Measures of center':{i:'🎯',what:'Mean, median, and mode describe the "center" of data.',steps:['Mean uses every value → outliers pull it.','Median is the middle → resists outliers.','Mode is the most common value.'],ex:{q:'2, 3, 4, 100',a:['Mean = 109 ÷ 4 = 27.25.','Median = 3.5.','The outlier 100 moved the mean, not the median.']},tip:'Skewed data (like incomes)? Use the median.'},
'Hypothesis testing':{i:'🧪',what:'We test a claim by asking how surprising our data would be if the null hypothesis were true.',steps:['Pick α (often 0.05).','If p < α → reject H₀.','If p ≥ α → fail to reject H₀ (never "accept").'],ex:{q:'p = 0.02, α = 0.05',a:['0.02 < 0.05.','Reject H₀ — the result is statistically significant.']},tip:'"If p is low, the null must go."'},
// ---- Reading & Writing ----
'Rhyming':{i:'🎵',what:'Rhyming words end with the same sound.',steps:['Say the word out loud.','Listen to the END sound.','Find the word that ends the same way.'],ex:{q:'What rhymes with "cat"?',a:['cat ends with "-at".','h-at, b-at, m-at all end with "-at".','"hat" rhymes with "cat"!']},tip:'Only the first sound changes: c-at, h-at, s-at.'},
'Phonics':{i:'🔤',what:'Every word starts with a sound, and letters make those sounds.',steps:['Say the word slowly.','Listen to the very first sound.','Which letter makes that sound?'],ex:{q:'What letter does "ball" start with?',a:['Say it slowly: b-b-ball.','The first sound is /b/.','The letter is B.']},tip:'C and K can make the same sound: "cup" and "kite".'},
'Sight words':{i:'👀',what:'Sight words show up all the time, so we learn to know them right away.',steps:['Look at the whole word.','Say each letter.','Read it again fast!'],ex:{q:'Find "the"',a:['Letters: t - h - e.','That spells "the".']},tip:'Practice a few each day and they\'ll pop out at you in books.'},
'Letters':{i:'🔠',what:'Every letter has a big (capital) and small (lowercase) form.',steps:['Find the small letter.','Think of its big partner.'],ex:{q:'Big letter for "g"?',a:['g and G are the same letter.','Answer: G']},tip:'Names and the first word of a sentence start with a capital letter.'},
'Synonyms':{i:'👯',what:'Synonyms are words that mean the same (or almost the same) thing.',steps:['Think about what the word means.','Find the word you could swap in.'],ex:{q:'Synonym for "big"?',a:['big = large size','"large" means the same thing.']},tip:'Test it: "a big dog" → "a large dog". Same meaning? It\'s a synonym!'},
'Antonyms':{i:'↔️',what:'Antonyms are words that mean the opposite.',steps:['Think about what the word means.','Think of its opposite.'],ex:{q:'Antonym of "hot"?',a:['hot ↔ cold.']},tip:'Some opposites add "un-" or "dis-": happy → unhappy.'},
'Compound words':{i:'🧱',what:'A compound word is two small words stuck together.',steps:['Look for a small word you know at the start.','The rest is another word.'],ex:{q:'"snowman"',a:['snow + man = snowman']},tip:'The meaning often comes from both parts: a toothbrush brushes teeth!'},
'Capitals & periods':{i:'✏️',what:'Sentences start with a capital letter and end with a punctuation mark.',steps:['First word starts with a capital.','End with . ? or !'],ex:{q:'Fix: "the dog ran"',a:['Capital T: "The".','Add a period: "The dog ran."']},tip:'The word "I" is always a capital.'},
'Plurals':{i:'🐑',what:'Plural means more than one.',steps:['Most words: add -s (cat → cats).','Ends in s, x, ch, sh: add -es (box → boxes).','Consonant + y: change y to i, add -es (baby → babies).','Some are irregular: child → children, mouse → mice.'],ex:{q:'Plural of "leaf"?',a:['Many f-words change f to v.','leaf → leaves']},tip:'Irregular ones just have to be remembered — tooth/teeth, foot/feet.'},
'Parts of speech':{i:'🏷️',what:'Words have jobs in a sentence.',steps:['Noun: person, place, or thing (dog, school).','Verb: an action (run, think).','Adjective: describes a noun (blue, brave).','Adverb: describes a verb (quickly).'],ex:{q:'"The brave dog ran."',a:['dog = noun','ran = verb','brave = adjective (describes the dog)']},tip:'Can you DO it? Verb. Can you point to it? Noun. Does it describe? Adjective.'},
'Prefixes':{i:'🔧',what:'A prefix goes at the START of a word and changes its meaning.',steps:['Find the prefix.','Know what it means.','Add it to the base word\'s meaning.'],ex:{q:'"replay"',a:['re- = again','replay = play again']},tip:'un- = not, re- = again, pre- = before, mis- = wrongly, dis- = opposite.'},
'Homophones':{i:'👂',what:'Homophones sound the same but are spelled differently and mean different things.',steps:['their = belongs to them','there = a place','they\'re = they are','its = belongs to it; it\'s = it is','your = belongs to you; you\'re = you are'],ex:{q:'___ going to the park.',a:['Try "they are": "They are going to the park." ✓','So use "They\'re".']},tip:'Apostrophe words are short for two words. Try saying them the long way!'},
'Figurative language':{i:'🎨',what:'Figurative language says things in creative, not literal, ways.',steps:['Simile: compares with "like" or "as".','Metaphor: says one thing IS another.','Personification: human actions for non-human things.','Hyperbole: huge exaggeration.','Onomatopoeia: sound words (buzz, pop).','Alliteration: same starting sound repeated.'],ex:{q:'"The stars winked at me."',a:['Stars can\'t really wink — that\'s a human action.','Personification!']},tip:'Look for "like" or "as" first. If it\'s there, it\'s probably a simile.'},
'Punctuation':{i:'❗',what:'Punctuation marks help readers know where to pause and stop.',steps:['Commas separate items in a list: eggs, milk, and bread.','Comma after "Yes," "Wait," or an opening phrase.','its = belongs to it; it\'s = it is.','Plural ending in s: apostrophe after the s (the girls\' room).'],ex:{q:'Fix: "We need eggs milk and bread"',a:['Commas between list items.','End with a period.','"We need eggs, milk, and bread."']},tip:'Read it out loud — pause where a comma should go.'},
'Vocabulary':{i:'📖',what:'Learning new words helps you read and write better.',steps:['Read the word in a sentence.','Use clues from the words around it.','Swap in the answer — does the sentence still make sense?'],ex:{q:'"The cautious cat crept slowly toward the dog."',a:['Clue: "crept slowly".','cautious = careful.']},tip:'Use one new word in a sentence today to make it stick!'},
'Roots':{i:'🌱',what:'Many English words are built from Greek and Latin roots.',steps:['Find the root inside the word.','Know what the root means.','Put the meaning together with the rest.'],ex:{q:'"telephone"',a:['tele = far','phon = sound','telephone = sound from far away']},tip:'Learn one root and you unlock lots of words: spect → spectator, inspect, spectacle.'},
'Reading passages':{i:'🔎',what:'Good readers find proof in the text for every answer.',steps:['Read the question first.','Read the passage and look for the part that answers it.','Pick the choice the passage backs up — not just one that sounds nice.'],ex:{q:'"Lena watered the seed every day." How did Lena care for the seed?',a:['Find the clue: "watered … every day".','Answer: she watered it every day.']},tip:'Main idea = what the WHOLE passage is mostly about, often in the first sentence.'},
'Rhetoric & literary devices':{i:'🎭',what:'Writers and speakers use devices to persuade and create effects.',steps:['Ethos = credibility, Pathos = emotion, Logos = logic/facts.','Irony: verbal (say the opposite), situational (opposite happens), dramatic (audience knows more).','Repetition: anaphora (same start), antithesis (opposites side by side), chiasmus (reversed order).','Others: oxymoron, litotes, synecdoche, metonymy, apostrophe, allusion, imagery.'],ex:{q:'"A deafening silence."',a:['Two opposite words together: deafening + silence.','That\'s an oxymoron.']},tip:'Ask: what EFFECT is the writer going for? That points to the device.'},
'Grammar & usage':{i:'🛠️',what:'Standard grammar rules make writing clear.',steps:['Subject–verb agreement: find the real subject (ignore "of the …").','Pronouns: subject (I, he) vs. object (me, him).','who = he/she, whom = him/her.','fewer for countable things, less for amounts.'],ex:{q:'The box of crayons ___ on the desk.',a:['Real subject: "box" (singular).','"of crayons" is extra.','The box … is.']},tip:'Cross out prepositional phrases to find the true subject.'},
'Sentence editing':{i:'✂️',what:'Good revisions are clear, correct, and concise.',steps:['Fix run-ons and fragments.','Make lists parallel (all -ing, or all "to ___").','Put the doer right after an opening phrase (no dangling modifiers).','Cut repeated or extra words.'],ex:{q:'"Running to class, my books fell."',a:['The books weren\'t running!','"Running to class, I dropped my books."']},tip:'Shorter is usually better, if the meaning stays the same.'},
'Argument & evidence':{i:'⚖️',what:'Strong arguments use relevant evidence and avoid fallacies.',steps:['Claim = a debatable statement. Evidence = facts, data, examples.','Best evidence is specific and directly supports the claim.','Fallacies: ad hominem, straw man, false dilemma, slippery slope, bandwagon, hasty generalization, false cause, circular reasoning.'],ex:{q:'"Everyone has one, so it must be good."',a:['Popularity isn\'t proof.','Bandwagon fallacy.']},tip:'Ask: does this evidence actually PROVE the claim, or just sound convincing?'}
};
// older students get more detailed versions of a few cards
const STUDY_HS={
'Punctuation':{i:'❗',what:'Advanced punctuation joins and separates ideas precisely.',steps:['Semicolon (;) joins two complete sentences.','Colon (:) introduces a list or explanation after a complete sentence.','Commas around nonessential (extra) info; dashes come in pairs around interruptions.','Comma + FANBOYS (for, and, nor, but, or, yet, so) joins two sentences. A comma alone = comma splice.','Quote inside a quote → single quotation marks.'],ex:{q:'"It rained, we stayed inside."',a:['Two complete sentences joined by just a comma = comma splice.','Fix: "It rained; we stayed inside."']},tip:'Test a semicolon: could each side stand alone as a sentence? If yes, it works.'},
'Vocabulary':{i:'📖',what:'SAT-level words often share roots and connotations you can decode.',steps:['Break it into parts (prefix / root / suffix).','Think of related words you already know.','Decide if it\'s positive or negative (connotation).','Eliminate choices that don\'t fit, then plug in.'],ex:{q:'"benevolent"',a:['bene = good, vol = wish.','Wishing good → kind.']},tip:'Make flashcards with a sentence on the back — context makes words stick.'},
'Roots':{i:'🌱',what:'Greek and Latin roots unlock thousands of advanced words.',steps:['Spot the root: chron, culp, loqu, morph, anthrop, pseudo…','Combine with prefixes and suffixes.'],ex:{q:'"anachronism"',a:['ana = back, chron = time.','Something out of its time.']},tip:'Learn roots in families: bene/mal, philo/phobia, pre/post.'},
'Reading passages':{i:'🔎',what:'Advanced reading questions ask about purpose, tone, and the author\'s attitude.',steps:['Main purpose: what is the author DOING (arguing, explaining, comparing)?','Tone: pick the word that matches the feeling of the word choices.','Vocabulary in context: plug each choice into the sentence.','Every answer must be supported by specific words in the text.'],ex:{q:'"…though the causes were surely more complex."',a:['"Though" signals a contrast; "surely more complex" shows doubt.','Attitude: cautiously skeptical.']},tip:'Extreme words (always, never, wholly) are usually wrong in answer choices.'}
};
var studyFor=function(skill,level){const hs=['9','10','11','12','College'].includes(String(level));return(hs&&STUDY_HS[skill])||STUDY[skill]||null;};
if(typeof module!=='undefined')Object.assign(module.exports,{STUDY,STUDY_HS,studyFor});
